# -*- coding: utf-8 -*-
# (speaker, italiano, coreano); speaker None => didascalia, "#" => titolo di scena (nessuno dei due conta come battuta)
C, R, S, W, SA, G, GI = "Chiara", "Renzo", "Simone", "Watanabe", "Sato", "Graziella", "Giulia"
D = [
("#", "Scena 1 — Martedì 16 dicembre, ore 8.30. Il laboratorio di Scandicci, il banco di Renzo.", "장면 1 — 12월 16일 화요일 오전 8시 30분. 스칸디치 공방, 렌초의 작업대."),
(None, "Fuori c'è la nebbia dell'Arno. Dentro, la stufa elettrica sotto il banco e l'odore di cuoio e di colla di pesce. Renzo ha le mani in un guanto di lana senza dita. Davanti a lui, una borsa color tabacco quasi finita: un manico solo, una piega morbida sul fianco. Chiara entra con due caffè.", "밖에는 아르노강의 안개. 안에는 작업대 밑 전기난로, 가죽과 생선 아교 냄새. 렌초는 손가락 없는 털장갑을 끼고 있다. 그 앞에 거의 다 된 담배색 가방이 놓여 있다. 손잡이 하나, 옆면의 부드러운 주름. 키아라가 커피 두 잔을 들고 들어온다."),
(C, "Buongiorno, Renzo. Sei qui da quando?", "좋은 아침이에요, 렌초. 언제부터 와 있었어요?"),
(R, "Dalle sette. Le mani la mattina sono di legno. Bisogna dar loro tempo di diventare mani.", "7시부터. 손이 아침엔 나무토막이야. 손이 손이 될 시간을 줘야지."),
(C, "Il fisioterapista ha detto di non lavorare col freddo.", "물리치료사가 추울 땐 일하지 말랬잖아요."),
(R, "Il fisioterapista non ha mai finito una borsa a dicembre. (indica la borsa) Guarda qui. Manca il bordo del manico e il cartellino.", "물리치료사는 12월에 가방 하나 끝내 본 적이 없어. (가방을 가리키며) 여기 봐. 손잡이 가장자리하고 택만 남았어."),
(C, "È per la mamma, vero? Me l'ha detto Simone.", "엄마 거죠? 시모네가 말해 줬어요."),
(R, "Simone ha la lingua lunga quanto il filo che spreca.", "시모네는 낭비하는 실만큼이나 입이 길어."),
(C, "Non ne ha sprecato un centimetro da settembre. Gliel'ho misurato io.", "9월부터 1센티도 낭비 안 했어요. 제가 재 봤어요."),
(R, "Lo so. Era per dire. (sorride) Sì, è per la signora. È l'ultima che faccio da... come dite voi? Da tempo pieno.", "알아. 그냥 해 본 소리야. (미소 지으며) 그래, 사모님 거야. 내가 마지막으로 만드는 거지… 너희 말로 뭐라더라? 전일제로."),
(C, "L'ultima da tempo pieno. Dopo, tre giorni alla settimana.", "전일제로는 마지막. 그다음은 일주일에 사흘."),
(R, "Lunedì, mercoledì e venerdì. Il venerdì perché ci sono i bomboloni di tuo fratello, mica per altro.", "월요일, 수요일, 금요일. 금요일은 네 오빠 봄볼로니 때문이지, 다른 이유는 없어."),
(C, "E il martedì e il giovedì?", "그럼 화요일하고 목요일은요?"),
(R, "Il martedì e il giovedì faccio fare a Simone quello che facevo io. E io sto a guardare. È la cosa più difficile del mestiere.", "화요일, 목요일엔 내가 하던 걸 시모네한테 시키고 나는 보기만 할 거야. 그게 이 일에서 제일 어려운 거지."),
(C, "A settembre te ne volevi andare per sempre. Adesso tieni tre giorni. Cos'è cambiato?", "9월엔 영영 떠나려고 했잖아요. 이제는 사흘을 남겨 두고요. 뭐가 달라졌어요?"),
(R, "Una lettera. E una ragazza che ha spedito quaranta borse da sola.", "편지 한 통. 그리고 혼자서 가방 마흔 개를 부친 아가씨."),
(C, "Non ero sola. C'erano Simone, Loredana, Marisa, Giulia...", "혼자 아니었어요. 시모네, 로레다나, 마리사, 줄리아도 있었고…"),
(R, "Eri sola nella testa. Lo so perché ci sono stato anch'io, nel sessantasei, quando il nonno Ugo si ammalò per un mese e il laboratorio restò a un ragazzino di tredici anni.", "머릿속으론 혼자였지. 나도 겪어 봐서 알아. 66년에 우고 할아버지가 한 달을 앓아누우셨을 때, 공방이 열세 살짜리 꼬마한테 남겨졌거든."),
(C, "Non me l'avevi mai raccontato.", "그 얘긴 한 번도 안 해 줬잖아요."),
(R, "Non me l'avevi mai chiesto. In questo laboratorio le cose si raccontano solo a chi rimane.", "한 번도 안 물어봤잖아. 이 공방에선 남는 사람한테만 이야기를 해 주는 거야."),
(C, "Allora rimango. Ma tu insegnami il bordo del manico. Quello vero, quello delle tre passate.", "그럼 남을게요. 대신 손잡이 가장자리를 가르쳐 줘요. 진짜로, 세 번 칠하는 그거요."),
(R, "Te lo insegno il mercoledì. Il mercoledì le mani mi funzionano meglio.", "수요일에 가르쳐 주마. 수요일엔 손이 좀 더 말을 들어."),
(C, "Perché proprio il mercoledì?", "왜 하필 수요일이에요?"),
(R, "Non lo so. Forse perché è a metà settimana, come me.", "모르지. 일주일의 한가운데라서 그런가, 나처럼."),
(None, "Simone arriva di corsa, il casco del motorino ancora in mano.", "시모네가 스쿠터 헬멧을 손에 든 채 뛰어 들어온다."),
(S, "Scusate! C'era la nebbia sulla Pisana, non si vedeva nulla.", "죄송해요! 피사나 도로에 안개가 껴서 아무것도 안 보였어요."),
(R, "Non si vedeva nulla, ma tu sei arrivato. Brava la nebbia. Posa il casco e prendi la lente.", "아무것도 안 보였는데 넌 왔네. 안개 착하다. 헬멧 내려놓고 루페 가져와."),
(S, "La lente? Per controllare cosa?", "루페요? 뭘 검사하려고요?"),
(R, "La mia borsa. La seconda mano oggi la fai tu. Su di me.", "내 가방. 오늘 '두 번째 손'은 네가 해. 나를 검사하는 거야."),
(S, "(si ferma) Io? Su di Lei? Maestro, io non posso...", "(멈춰 서며) 제가요? 선생님을요? 선생님, 전 못…"),
(R, "La regola è la regola. L'abbiamo scritta a maggio, quando i difetti erano i tuoi. Adesso vale anche per i miei.", "규칙은 규칙이야. 5월에 네 결함 때문에 만든 거잖아. 이제 내 것에도 적용되는 거지."),
(C, "Ha ragione, Simone. Nessuno è esentato. Nemmeno chi l'ha inventata.", "렌초 말이 맞아, 시모네. 예외는 없어. 그 규칙을 만든 사람도."),
(None, "Simone posa il casco, accende la lampada, prende la dima da quattro millimetri e la lente. Le mani gli tremano un poco. Passa la lente lungo la cucitura, angolo dopo angolo, in silenzio.", "시모네가 헬멧을 내려놓고 램프를 켜고 4밀리미터 템플릿과 루페를 집는다. 손이 조금 떨린다. 루페로 바느질선을 모서리마다 따라가며 말없이 본다."),
(S, "Quattro millimetri... quattro... quattro. Il bordo è dentro la linea. (pausa) Qui. All'attacco del manico, a sinistra. C'è un punto più tirato degli altri.", "4밀리… 4… 4. 가장자리는 선 안이에요. (잠시 멈추고) 여기요. 손잡이 연결부 왼쪽. 다른 땀보다 더 당겨진 땀이 하나 있어요."),
(R, "(prende la lente, guarda a lungo) Hai ragione. È il dito che non chiude bene la mattina.", "(루페를 받아 오래 들여다보며) 네 말이 맞네. 아침에 잘 안 굽혀지는 손가락 탓이야."),
(C, "Lo rifai?", "다시 할 거예요?"),
(R, "Un punto solo. Dieci minuti. (a Simone) E tu scrivi il cartellino.", "한 땀만. 10분. (시모네에게) 그리고 넌 택을 써."),
(S, "« Cucita da Renzo. Controllata da Simone. » Davvero lo devo scrivere io?", "'바느질: 렌초. 검사: 시모네.' 정말 제가 써야 해요?"),
(R, "Con la tua calligrafia. Quella brutta. Così la signora capisce che il mondo è cambiato.", "네 글씨로. 그 못생긴 글씨로. 그래야 사모님이 세상이 바뀌었다는 걸 아시지."),
(C, "E il nome? Ogni borsa ha un nome di un posto qui intorno.", "이름은요? 가방마다 이 근처 지명을 붙이잖아요."),
(R, "Questa no. Questa non va in negozio. Ha un nome solo: quello della persona che la porta.", "이건 아니야. 이건 매장에 안 나가. 이름은 하나뿐이야. 이걸 들고 다닐 사람의 이름."),
(C, "Allora la chiamo come la mamma la chiama quando non sa come chiamare le cose: « quella lì ».", "그럼 엄마가 뭐라고 부를지 모를 때 부르는 대로 할게요. '그거'."),
(R, "(ride) « Quella lì ». Va bene. Il nonno Ugo chiamava così anche me, il primo anno.", "(웃으며) '그거'. 좋아. 우고 할아버지도 첫해엔 나를 그렇게 불렀어."),

("#", "Scena 2 — Ore 11.15. Il cortile e il laboratorio.", "장면 2 — 오전 11시 15분. 마당과 공방."),
(None, "Un taxi bianco si ferma davanti al cancello. Scendono il signor Watanabe, cappotto grigio e sciarpa blu, e la signorina Sato, con una valigetta di cuoio. Sono le undici e dieci: cinque minuti di anticipo.", "흰 택시가 정문 앞에 선다. 회색 코트에 파란 목도리를 한 와타나베 씨와 가죽 서류 가방을 든 사토 씨가 내린다. 11시 10분. 5분 일찍이다."),
(W, "Buongiorno, signora Corsini. Le chiedo scusa: siamo in anticipo. A Roma mi dicevano che era un difetto.", "안녕하세요, 코르시니 씨. 죄송합니다, 일찍 왔습니다. 로마에선 그게 결점이라고들 했지요."),
(C, "Qui è un complimento. Benvenuti a Scandicci. È la prima volta?", "여기선 칭찬이에요. 스칸디치에 오신 걸 환영해요. 처음이세요?"),
(W, "A Scandicci sì. A Firenze, l'ultima volta, avevo trent'anni e i capelli neri.", "스칸디치는 처음입니다. 피렌체는, 마지막으로 왔을 때 서른 살이었고 머리가 까맸지요."),
(SA, "Io invece ci ho abitato due anni, in via dei Serragli. Restauravo carte antiche. Non sono mai venuta fin qui.", "저는 피렌체에 2년 살았어요, 세라글리 거리에서요. 고문서 복원을 했어요. 여기까지는 와 본 적이 없네요."),
(C, "Allora vi faccio vedere tutto. Ma prima vi presento due persone. Il nostro maestro, Renzo Paoli. E Simone.", "그럼 전부 보여 드릴게요. 그 전에 두 사람을 소개할게요. 저희 장인 렌초 파올리. 그리고 시모네."),
(W, "(si inchina appena) Signor Paoli. Ho sulla scrivania, a Tokyo, la Sua fotografia. Le Sue mani, cioè. Sul catalogo.", "(살짝 고개를 숙이며) 파올리 씨. 도쿄 제 책상에 선생님 사진이 있습니다. 정확히는 선생님 손이요. 카탈로그 표지에서."),
(R, "Le mani sono venute meglio della faccia. Piacere, signor Watanabe.", "손이 얼굴보다 잘 나왔지요. 반갑습니다, 와타나베 씨."),
(SA, "(a Simone) Tu sei Simone. Quello dei sei pezzi di maggio.", "(시모네에게) 당신이 시모네군요. 5월의 그 여섯 개."),
(S, "(arrossisce) Sì. Sono io. Mi dispiace ancora.", "(얼굴이 빨개지며) 네. 저예요. 아직도 죄송해요."),
(SA, "Non deve dispiacersi. Il Suo bigliettino su quel ritaglio di cuoio è appeso nel nostro retrobottega. Lo leggono tutti i nuovi commessi il primo giorno.", "미안해하실 필요 없어요. 그 가죽 조각에 쓴 쪽지는 저희 가게 뒷방에 걸려 있어요. 새 직원은 첫날 모두 그걸 읽어요."),
(S, "Davvero? E cosa ci capiscono? Era in italiano.", "정말요? 뭘 알아듣겠어요? 이탈리아어였는데."),
(W, "Gliel'ho tradotto io. « Ho sbagliato perché avevo fretta. La prossima volta chiedo. » È la migliore lezione di qualità che abbiamo in negozio.", "제가 번역했지요. '서둘러서 틀렸습니다. 다음엔 묻겠습니다.' 저희 가게에 있는 최고의 품질 교육입니다."),
(C, "Prima del banco, vi mostro il tavolo del controllo. L'abbiamo messo vicino alla finestra a nord, come ci ha insegnato la signorina Sato.", "작업대 전에 검사대를 보여 드릴게요. 사토 씨가 알려 준 대로 북쪽 창가에 두었어요."),
(SA, "La finestra a nord non cambia luce durante il giorno. È l'unica cosa che vi ho insegnato io. Il resto l'avete fatto da soli.", "북쪽 창은 하루 종일 빛이 바뀌지 않아요. 제가 가르쳐 드린 건 그것뿐이에요. 나머지는 여러분이 스스로 하신 거고요."),
(C, "Ogni borsa del marchio passa da qui. Quattro minuti, la dima, la lente, la lampada. Due nomi sul cartellino.", "브랜드 가방은 전부 여기를 거쳐요. 4분, 템플릿, 루페, 램프. 택에는 이름 두 개."),
(W, "Quante borse avete fermato, da maggio?", "5월 이후로 몇 개를 멈춰 세우셨습니까?"),
(C, "Undici su milleduecento. Nessuna difettosa è uscita. Nove le ha fermate Simone.", "1,200개 중에 열한 개요. 결함품은 하나도 안 나갔어요. 아홉 개는 시모네가 잡았고요."),
(S, "E due le ha fermate Loredana. Su di me.", "그리고 두 개는 로레다나가 잡았어요. 제 거요."),
(W, "Allora il metodo è cambiato. È quello che avevo chiesto a maggio.", "그렇다면 방법이 바뀐 거군요. 제가 5월에 부탁드린 게 바로 그겁니다."),
(C, "Venite al banco. Renzo ha appena finito una borsa. E Simone l'ha appena controllata.", "작업대로 오세요. 렌초가 방금 가방 하나를 끝냈어요. 그리고 시모네가 방금 그걸 검사했고요."),
(W, "Il ragazzo controlla il maestro?", "청년이 장인을 검사합니까?"),
(R, "Da stamattina. E mi ha trovato un punto storto. Uno. In trent'anni nessuno ha mai osato.", "오늘 아침부터요. 그리고 비뚤어진 땀을 하나 찾아냈어요. 하나. 30년 동안 아무도 감히 그러지 못했는데."),
(SA, "Posso guardare anch'io?", "저도 봐도 될까요?"),
(C, "Prego. Sotto la lampada.", "그럼요. 램프 밑에서요."),
(None, "Sato apre la valigetta, tira fuori la sua lente e un panno grigio. Guarda la borsa come guarderebbe una pergamena. Nessuno parla. Fuori, un motorino passa nella nebbia.", "사토가 가방을 열어 자기 루페와 회색 천을 꺼낸다. 양피지를 보듯 가방을 본다. 아무도 말하지 않는다. 밖에서 스쿠터 한 대가 안개 속을 지나간다."),
(SA, "Il punto rifatto si vede appena. Perché è rifatto meglio degli altri.", "다시 한 땀은 거의 안 보여요. 다른 땀보다 더 잘 다시 했으니까요."),
(R, "Questa è la frase più bella che mi abbiano detto quest'anno. E l'anno è stato lungo.", "올해 들은 말 중에 제일 좋은 말이네요. 길었던 한 해였는데."),
(W, "Signora Corsini, posso farle una domanda che a Tokyo si fa solo a cena?", "코르시니 씨, 도쿄에선 저녁 자리에서만 하는 질문을 하나 드려도 될까요?"),
(C, "Qui le domande si fanno a pranzo. Ma la faccia pure.", "여기선 질문을 점심때 해요. 그래도 하세요."),
(W, "Il signor Paoli smette?", "파올리 씨가 그만두십니까?"),
(R, "Non smetto. Rallento. Tre giorni alla settimana. Il resto lo fanno loro, e io sto a guardare.", "안 그만둬요. 속도를 줄이는 거지요. 일주일에 사흘. 나머지는 이 사람들이 하고 나는 지켜보고."),
(W, "In Giappone abbiamo una parola per questo. Non è « pensione ». È passare la mano senza lasciarla andare.", "일본에는 그걸 가리키는 말이 있습니다. '은퇴'가 아니에요. 손을 넘기되 놓지는 않는 것."),
(SA, "Il maestro del mio maestro di restauro veniva in laboratorio fino a novant'anni. Non toccava più niente. Guardava. E noi lavoravamo meglio.", "제 복원 스승의 스승은 아흔 살까지 작업실에 나왔어요. 더는 아무것도 만지지 않았어요. 보기만 했어요. 그런데 저희가 더 잘 일했어요."),
(R, "Allora ho ancora diciotto anni di mestiere. Simone, segna.", "그럼 나한테 아직 18년이 남았네. 시모네, 적어 둬."),
(S, "Segnato, maestro.", "적었어요, 선생님."),

("#", "Scena 3 — Ore 17.30. Firenze, via Tornabuoni, il negozio temporaneo « Corsini Scandicci ».", "장면 3 — 오후 5시 30분. 피렌체 토르나부오니 거리, '코르시니 스칸디치' 임시 매장."),
(None, "Il negozio ha aperto sabato. Al centro, un vecchio banco da lavoro di castagno. Lungo la parete di fondo, ventinove borse su ventinove mensole, ciascuna con un cartellino scritto a mano: un anno, dal 1997 al 2025. Sopra, una sola scritta: « Ventinove anni. Ventinove borse. Nessuna in vendita. » Fuori, le luci di Natale sulla strada.", "매장은 토요일에 문을 열었다. 한가운데 오래된 밤나무 작업대. 안쪽 벽을 따라 선반 29개에 가방 29개, 각각 손글씨 택이 달려 있다. 1997년부터 2025년까지, 한 해에 하나. 그 위에 문구 하나. '29년. 가방 29개. 판매하지 않음.' 밖에는 거리의 성탄 조명."),
(GI, "Zia, da sabato ne avranno fotografate mille. Il post ha trecentomila visualizzazioni.", "고모, 토요일부터 사진을 천 번은 찍었을 거예요. 게시물 조회 수가 30만이에요."),
(C, "E quante borse abbiamo venduto, di quelle in vendita?", "그럼 파는 가방은 몇 개나 팔았어?"),
(GI, "Trentaquattro in tre giorni. E undici persone hanno chiesto di comprare una di quelle là. Ho risposto sempre uguale: « Non sono in vendita. Sono la nostra memoria. »", "사흘에 서른네 개요. 그리고 열한 명이 저쪽 벽 가방을 사고 싶다고 했어요. 늘 똑같이 대답했어요. '판매하지 않습니다. 저희의 기억이에요.'"),
(C, "Brava. E chi ti ha insegnato a dire « memoria »?", "잘했어. 그런데 '기억'이라고 말하는 건 누구한테 배웠어?"),
(GI, "La nonna. Dice che una famiglia senza memoria è come una borsa senza fodera: sembra uguale, ma si sfonda.", "할머니요. 기억 없는 가족은 안감 없는 가방 같대요. 겉보기엔 똑같은데 바닥이 터진다고요."),
(C, "La nonna non ha mai detto una cosa del genere.", "할머니는 그런 말 한 적 없어."),
(GI, "Infatti l'ho detta io. Però suona come lei, no?", "맞아요, 제가 한 말이에요. 근데 할머니 말처럼 들리잖아요, 그렇죠?"),
(None, "Entrano Watanabe e Sato. Watanabe si ferma davanti alla parete e non si muove per un lungo momento.", "와타나베와 사토가 들어온다. 와타나베가 벽 앞에 멈춰 서서 한참 움직이지 않는다."),
(W, "Il 1997 è la più semplice. Il 2008 è la più triste.", "1997년 것이 제일 단순하군요. 2008년 것이 제일 슬프고."),
(C, "Come fa a saperlo? Il 2008 è l'anno della crisi. Renzo usò gli scarti, perché non c'era cuoio per noi.", "어떻게 아세요? 2008년은 위기의 해였어요. 저희 몫으로 쓸 가죽이 없어서 렌초가 자투리로 만들었어요."),
(W, "Si vede dalle cuciture. Più fitte. Quando non si ha materiale, si mette più lavoro.", "바느질에서 보입니다. 땀이 더 촘촘해요. 재료가 없으면 일을 더 넣는 법이지요."),
(SA, "E il 2020 non ha manico. Solo una tracolla corta.", "그리고 2020년 것은 손잡이가 없네요. 짧은 끈만."),
(C, "Il 2020 l'ha fatta a casa sua, durante il primo lockdown. Senza la macchina per i manici.", "2020년 건 렌초가 첫 봉쇄 때 집에서 만든 거예요. 손잡이 기계 없이."),
(W, "Signora Corsini, so la risposta, ma la devo fare lo stesso. Non posso comprarne una.", "코르시니 씨, 답은 알지만 그래도 여쭤야겠습니다. 하나 살 수는 없겠지요."),
(C, "No. Ma può portarle a Tokyo.", "네. 하지만 도쿄로 모셔 갈 수는 있어요."),
(W, "(si volta) Portarle?", "(돌아보며) 모셔 간다고요?"),
(C, "In primavera. Tutte e ventinove, per un mese, al Kōbō. Con Renzo, se le sue mani se la sentono di volare. Se no, con Simone.", "봄에요. 스물아홉 개 전부, 한 달 동안, 고보에서. 렌초 손이 비행기를 견딜 수 있으면 렌초와 함께. 아니면 시모네와 함께."),
(SA, "Il nostro piano di sopra è piccolo. Ventinove mensole non ci stanno.", "저희 2층은 좁아요. 선반 스물아홉 개는 안 들어가요."),
(W, "Ci staranno. Toglierò la mia scrivania.", "들어갈 겁니다. 제 책상을 빼지요."),
(None, "La porta si apre. Graziella entra con il cappotto scuro e il foulard di seta. Dietro di lei Renzo, con un pacco avvolto nella carta da pacchi e legato con lo spago.", "문이 열린다. 짙은 코트에 실크 스카프를 한 그라치엘라가 들어온다. 그 뒤로 렌초가 포장지로 싸고 노끈으로 묶은 꾸러미를 들고 온다."),
(G, "Che bella gente stasera. Signor Watanabe, finalmente. Mia figlia mi ha detto che Lei è puntuale come un orologio svizzero.", "오늘 저녁 사람들이 참 좋네요. 와타나베 씨, 드디어 뵙네요. 딸이 그러는데 스위스 시계처럼 시간을 지키신다고요."),
(W, "Giapponese, signora. Gli svizzeri ci copiano.", "일본 시계지요, 사모님. 스위스가 저희를 베끼는 겁니다."),
(G, "(ride) Mi piace. Renzo, cos'ha in mano? Sembra un pacco della posta di guerra.", "(웃으며) 마음에 드네요. 렌초, 손에 든 게 뭐예요? 전쟁 때 우편 소포 같아요."),
(R, "È per Lei, signora. Non è Natale, lo so. Ma a Natale volevo essere a tavola con le mani libere.", "사모님 거예요. 아직 성탄절이 아닌 건 알아요. 하지만 성탄절엔 빈손으로 식탁에 앉고 싶었어요."),
(None, "Graziella scioglie lo spago con calma. Apre la carta. La borsa color tabacco. Il cartellino. Legge a voce bassa.", "그라치엘라가 천천히 노끈을 푼다. 포장지를 연다. 담배색 가방. 택. 낮은 목소리로 읽는다."),
(G, "« Quella lì. Cucita da Renzo. Controllata da Simone. » (alza gli occhi) Controllata da Simone?", "'그거. 바느질: 렌초. 검사: 시모네.' (눈을 들며) 검사가 시모네라고요?"),
(R, "Mi ha trovato un punto storto. L'ho rifatto.", "비뚤어진 땀을 하나 찾아냈어요. 다시 했지요."),
(G, "In quarantacinque anni, Renzo, Lei non mi ha mai detto di aver sbagliato un punto.", "45년 동안, 렌초, 땀 하나 틀렸다고 나한테 말한 적이 없었잖아요."),
(R, "Non me l'aveva mai trovato nessuno. È questa la notizia.", "아무도 찾아낸 적이 없었으니까요. 그게 오늘의 뉴스예요."),
(G, "E « quella lì » chi l'ha scritto?", "그리고 '그거'는 누가 쓴 거예요?"),
(C, "Io. È come la chiami tu quando non ti viene il nome.", "제가요. 엄마가 이름이 생각 안 날 때 부르는 말이잖아요."),
(G, "(ride, con gli occhi lucidi) Il tuo babbo diceva che con « quella lì » io comandavo mezza casa.", "(웃는데 눈가가 젖어 있다) 너희 아빠가 그랬지. 나는 '그거' 한마디로 집안 절반을 부린다고."),
(GI, "Nonna, la metti subito? Così faccio la foto.", "할머니, 지금 바로 들어 보세요. 사진 찍게요."),
(G, "La foto no. Le foto le fai alle borse in vendita. Questa la porto e basta.", "사진은 안 돼. 사진은 파는 가방이나 찍어. 이건 그냥 들고 다닐 거야."),
(None, "Graziella mette la borsa al braccio. Fa due passi davanti alla parete delle ventinove. Si ferma davanti al 1997.", "그라치엘라가 가방을 팔에 건다. 29개가 걸린 벽 앞을 두어 걸음 걷는다. 1997년 가방 앞에서 멈춘다."),
(G, "Questa la ricordo. Ugo la guardò e disse: « Renzo, l'hai fatta come se nessuno la dovesse comprare. » Era un complimento. Lui era così.", "이건 기억나요. 우고가 보고 그랬죠. '렌초, 아무도 안 살 것처럼 만들었구나.' 칭찬이었어요. 그분은 그런 사람이었죠."),
(R, "E aveva ragione. Nessuno l'ha comprata. È rimasta nell'armadio per ventotto anni.", "맞는 말씀이었어요. 아무도 안 샀죠. 28년 동안 장 안에 있었으니까."),
(W, "Signora, la Sua figlia mi ha proposto di portarle tutte a Tokyo, in primavera.", "사모님, 따님께서 이것들을 봄에 전부 도쿄로 가져가자고 제안하셨습니다."),
(G, "Mia figlia propone molte cose quando sono fuori dalla stanza. (a Chiara) Non è una brutta idea, però.", "내 딸은 내가 자리를 비우면 이것저것 제안을 많이 하지요. (키아라에게) 나쁜 생각은 아니구나."),
(C, "Allora ne parliamo a tavola. Giovedì è Natale.", "그럼 식탁에서 얘기해요. 목요일이 성탄절이니까."),
(G, "A Natale non si parla di lavoro. Si parla di tutto il resto, che è peggio. (a Watanabe) Signor Watanabe, Lei e la signorina Sato quanto restate?", "성탄절엔 일 얘기 안 해. 나머지 전부를 얘기하지. 그게 더 힘들어. (와타나베에게) 와타나베 씨, 사토 씨랑 언제까지 계세요?"),
(W, "Fino a venerdì. Poi Roma, per un giorno. Devo salutare una bottega che non c'è più.", "금요일까지요. 그다음 로마에 하루. 이제는 없는 공방에 인사를 해야 해서요."),
(SA, "La bottega di via dei Cappellari. Quella delle tre passate.", "카펠라리 거리의 공방이요. 세 번 칠하는 그곳."),
(W, "« Una passata è pittura, due sono fretta, tre sono pelle. » (a Renzo) Lei quante ne fa, signor Paoli?", "'한 번 칠하면 그림, 두 번이면 서두름, 세 번이면 가죽.' (렌초에게) 선생님은 몇 번 칠하십니까, 파올리 씨?"),
(R, "Tre. Ma da gennaio le conta Simone.", "세 번요. 그런데 1월부터는 시모네가 세요."),
(S, "Le conto ad alta voce, maestro. Così Lei non s'arrabbia.", "소리 내서 셀게요, 선생님. 그래야 화 안 내시죠."),
(R, "M'arrabbio lo stesso. Ma ascolto.", "그래도 화는 낼 거다. 하지만 들을 거야."),
(None, "Chiara spegne due faretti. Restano accese solo le luci sopra le ventinove borse. Fuori, la gente si ferma davanti alla vetrina.", "키아라가 스포트라이트 두 개를 끈다. 29개 가방 위의 불빛만 남는다. 밖에서 사람들이 진열창 앞에 멈춰 선다."),
(C, "Renzo, da lunedì il tuo banco resta lì dov'è. Anche il martedì e il giovedì.", "렌초, 월요일부터도 렌초 작업대는 그 자리에 그대로 있어요. 화요일하고 목요일에도."),
(R, "Lo so. Me l'ha scritto il tuo nonno.", "알아. 네 할아버지가 써 놓으셨잖아."),
(C, "Allora domani la rileggiamo insieme, la lettera. Il mercoledì, quando le mani funzionano.", "그럼 내일 그 편지 같이 다시 읽어요. 수요일, 손이 말 들을 때."),
(R, "Il mercoledì. E porta il caffè. Quello vero, non quello della macchinetta.", "수요일. 그리고 커피 가져와. 진짜 커피로, 자판기 거 말고."),
]

